```javascript
const jwt = require('jsonwebtoken');
const mysql = require('mysql2/promise');

// JWT token generation function
function generateToken(payload, secretKey) {
  const options = {
    algorithm: 'HS512',
    expiresIn: 3600 // 3600 seconds = 1 hour
  };
  return jwt.sign(payload, secretKey, options);
}

// Example usage of the JWT token generation
const secretKey = 'your-very-secure-secret-key';
const payload = { userId: 123, role: 'user' };
const token = generateToken(payload, secretKey);
console.log('Generated JWT:', token);

// Example database query using prepared statements
async function getUserById(userId) {
  const connection = await mysql.createConnection({
    host: 'localhost',
    user: 'dbuser',
    password: 'dbpassword',
    database: 'authdb'
  });

  const query = 'SELECT * FROM users WHERE id = ?';
  const [rows] = await connection.execute(query, [userId]);
  await connection.end();
  return rows;
}

// Example usage of the database query
getUserById(123).then(user => {
  console.log('User info:', user);
}).catch(err => {
  console.error('Database error:', err);
});
```

